-- Çok dilli SSS (EN / JA): yeni sütunlar ve çeviriler
ALTER TABLE sss ADD COLUMN IF NOT EXISTS soru_en TEXT, ADD COLUMN IF NOT EXISTS cevap_en TEXT, ADD COLUMN IF NOT EXISTS soru_ja TEXT, ADD COLUMN IF NOT EXISTS cevap_ja TEXT;
ALTER TABLE sss_kategorileri ADD COLUMN IF NOT EXISTS ad_en TEXT, ADD COLUMN IF NOT EXISTS ad_ja TEXT;
UPDATE sss_kategorileri SET ad_en = 'General', ad_ja = '一般' WHERE id = 1;
UPDATE sss_kategorileri SET ad_en = 'Education', ad_ja = '学歴' WHERE id = 2;
UPDATE sss_kategorileri SET ad_en = 'Projects', ad_ja = 'プロジェクト' WHERE id = 3;
UPDATE sss_kategorileri SET ad_en = 'Technologies', ad_ja = '技術' WHERE id = 4;
UPDATE sss_kategorileri SET ad_en = 'Contact', ad_ja = '連絡' WHERE id = 5;
UPDATE sss_kategorileri SET ad_en = 'Internship & Career', ad_ja = 'インターンシップとキャリア' WHERE id = 6;
UPDATE sss SET soru_en = 'Who are you?', cevap_en = 'I''m Kaan Semih Kurt, a final-year Big Data Analytics student. My interests and focus areas are data, data analysis, game development and programming languages.', soru_ja = 'あなたは誰ですか？', cevap_ja = 'カーン・セミフ・クルトです。ビッグデータ分析学科の最終学年の学生です。データ、データ分析、ゲーム開発、プログラミング言語に興味を持ち、力を入れています。' WHERE id = 1;
UPDATE sss SET soru_en = 'Which course was this site built for? (Student no: 2516016008)', cevap_en = 'It was developed as the database and admin panel assignment for the Cyber Security and IT Law course.', soru_ja = 'このサイトはどの授業のために作られましたか？（学籍番号：2516016008）', cevap_ja = '「サイバーセキュリティと情報法」の授業で、データベースと管理パネルの課題として開発しました。' WHERE id = 2;
UPDATE sss SET soru_en = 'What are you studying?', cevap_en = 'I''m a final-year student in the Big Data Analytics associate degree program at Manisa Celal Bayar University.', soru_ja = '何を専攻していますか？', cevap_ja = 'マニサ・ジェラル・バヤル大学のビッグデータ分析学科（短期大学課程）の最終学年に在籍しています。' WHERE id = 3;
UPDATE sss SET soru_en = 'What is the CPI data story project?', cevap_en = 'A scrollytelling data story site that offers a detailed analysis of the spending categories that have driven inflation the most over the last five years.', soru_ja = '消費者物価指数（TÜFE）データストーリーとは何ですか？', cevap_ja = '過去5年間でインフレに最も影響を与えた支出項目を詳しく分析した、スクロールで進むデータストーリーサイトです。' WHERE id = 4;
UPDATE sss SET soru_en = 'Where can I find the source code of your projects?', cevap_en = 'All my projects are on my GitHub account: github.com/kaansemihkurt', soru_ja = 'プロジェクトのソースコードはどこで見られますか？', cevap_ja = 'すべてのプロジェクトはGitHubアカウントにあります：github.com/kaansemihkurt' WHERE id = 5;
UPDATE sss SET soru_en = 'What did you study in high school?', cevap_en = 'I studied machine technology at MOSTEM and graduated in 2024.', soru_ja = '高校では何を学びましたか？', cevap_ja = 'MOSTEMで機械技術を学び、2024年に卒業しました。' WHERE id = 6;
UPDATE sss SET soru_en = 'What does Windows Performance Tuner do?', cevap_en = 'A PowerShell-based project for Windows 10/11 that turns off unnecessary services and settings that slow the computer down, and can undo every step in case of problems.', soru_ja = 'Windows Performance Tunerとは何ですか？', cevap_ja = 'Windows 10/11でパソコンを遅くする不要なサービスや設定を無効にし、問題が起きた場合はすべての手順を元に戻せるPowerShellベースのプロジェクトです。' WHERE id = 7;
UPDATE sss SET soru_en = 'What technologies was this site built with?', cevap_en = 'Next.js (App Router), PostgreSQL (Neon) and Vercel.', soru_ja = 'このサイトはどの技術で作られていますか？', cevap_ja = 'Next.js（App Router）、PostgreSQL（Neon）、Vercelを使用しています。' WHERE id = 8;
UPDATE sss SET soru_en = 'How can I contact you?', cevap_en = 'You can send me a message by filling in the form on the contact page.', soru_ja = 'どうすれば連絡できますか？', cevap_ja = 'お問い合わせページのフォームからメッセージを送ることができます。' WHERE id = 10;
UPDATE sss SET soru_en = 'How is my personal data protected?', cevap_en = 'Data sent through the contact form is used only to reply to you. Details are on the Privacy Notice page.', soru_ja = '個人情報はどのように守られていますか？', cevap_ja = 'お問い合わせフォームで送られたデータは、返信のためだけに使用されます。詳しくは「個人情報に関する通知」ページをご覧ください。' WHERE id = 11;
UPDATE sss SET soru_en = 'What are your hobbies?', cevap_en = 'Tinkering with computer hardware, playing games, learning new programming languages and building projects and programs that are useful to people.', soru_ja = '趣味は何ですか？', cevap_ja = 'パソコンのハードウェアをいじること、ゲーム、新しいプログラミング言語を学ぶこと、人の役に立つプロジェクトやプログラムを作ることです。' WHERE id = 13;
UPDATE sss SET soru_en = 'Do you accept freelance projects?', cevap_en = 'Yes, I do, depending on the topic. You can write to me from the contact page.', soru_ja = 'フリーランスの依頼は受けていますか？', cevap_ja = 'はい、内容によりますが受け付けています。お問い合わせページからご連絡ください。' WHERE id = 14;
